package com.example.discovery.consumer.api;import com.example.discovery.consumer.model.PaymentResponse;import com.example.discovery.consumer.service.PaymentService;import org.springframework.web.bind.annotation.*;@RestController public class PaymentController{private final PaymentService paymentService;public PaymentController(PaymentService paymentService){this.paymentService=paymentService;} @GetMapping("/payments") public PaymentResponse payments(){return paymentService.getPayments();}}
